1870	\begin{lemma}[Preimages of the charts are affine]
1871	  \label{lem:preimage_chart_affine}
1872	  \lean{AlgebraicGeometry.isAffineOpen_preimage_chartOpen}
1873	  \uses{def:P1_chartOpen}
1874	  \leanok
1875	  Let \(\pi : Y \to \PP^1\) be an affine morphism (for instance a finite one). Then
1876	  \(\pi^{-1}(U_i)\) is an affine open of \(Y\) for \(i \in \{0,1\}\).
1877	\end{lemma}
1878	\begin{proof}
1879	  \leanok
1880	  \uses{lem:P1_chartOpen_affine}
1881	  The charts are affine (\ref{lem:P1_chartOpen_affine}), and the preimage of an affine open
1882	  under an affine morphism is affine.
1883	\end{proof}
1884	
1885	\begin{lemma}[Preimages of the charts cover]
1886	  \label{lem:preimage_chart_sup}
1887	  \lean{AlgebraicGeometry.preimage_chartOpen_sup}
1888	  \uses{def:P1_chartOpen}
1889	  \leanok
1890	  For any morphism \(\pi : Y \to \PP^1\), the preimages of the two standard charts cover
1891	  \(Y\): \(\pi^{-1}(U_0) \cup \pi^{-1}(U_1) = Y\).
1892	\end{lemma}
1893	\begin{proof}
1894	  \leanok
1895	  \uses{lem:P1_chartOpen_sup}
1896	  Preimages of a cover form a cover (\ref{lem:P1_chartOpen_sup}).
1897	\end{proof}
1898	
1899	\begin{lemma}[Module-finiteness over the charts]
1900	  \label{lem:finite_app_chart}
1901	  \lean{AlgebraicGeometry.finite_app_chartOpen}
1902	  \uses{def:P1_chartOpen}
1903	  \leanok
1904	  Let \(\pi : Y \to \PP^1\) be a finite morphism. For \(i \in \{0,1\}\), the induced ring
1905	  homomorphism \(\Gamma(\PP^1, U_i) \to \Gamma(Y, \pi^{-1}(U_i))\) is module-finite. (By
1906	  \ref{def:P1_chartSectionsEquiv0}--\ref{def:P1_chartSectionsEquiv1}, the source is the
1907	  polynomial ring \(k[t]\).)
1908	\end{lemma}
1909	\begin{proof}
1910	  \leanok
1911	  \uses{lem:P1_chartOpen_affine}
1912	  A finite morphism induces module-finite maps on sections over affine opens; the charts are
1913	  affine by \ref{lem:P1_chartOpen_affine}.
1914	\end{proof}
1915	
1916	\begin{lemma}[Module-finiteness over the overlap]
1917	  \label{lem:finite_app_overlap}
1918	  \lean{AlgebraicGeometry.finite_app_overlap}
1919	  \uses{lem:P1_chartOpen_inf}
1920	  \leanok
1921	  Let \(\pi : Y \to \PP^1\) be a finite morphism. The induced ring homomorphism
1922	  \(\Gamma(\PP^1, U_0 \cap U_1) \to \Gamma(Y, \pi^{-1}(U_0 \cap U_1))\) is module-finite.
1923	  (By \ref{def:P1_overlapSectionsEquiv}, the source is the Laurent polynomial ring
1924	  \(k[T,T^{-1}]\).)
1925	\end{lemma}
1926	\begin{proof}
1927	  \leanok
1928	  \uses{lem:P1_overlap_affine}
1929	  As in \ref{lem:finite_app_chart}, with the overlap affine by \ref{lem:P1_overlap_affine}.
1930	\end{proof}
